const DRAFTS = DATA.drafts;
const SYSTEM = DATA.system;

const MEDIUMS: { id: Medium; label: string }[] = [
  { id: "blog", label: "Blog" },
  { id: "linkedin", label: "LinkedIn" },
  { id: "x", label: "X" },
  { id: "talk", label: "Talk" },
];

const PANES: { id: Pane; label: string }[] = [
  { id: "generate", label: "Generator prompt" },
  { id: "extract", label: "Extraction prompt" },
  { id: "output", label: "Model output" },
];

function chatWrapped(user: string): string {
  return (
    "<|begin_of_text|><|start_header_id|>system<|end_header_id|>\n\n" +
    SYSTEM +
    "<|eot_id|><|start_header_id|>user<|end_header_id|>\n\n" +
    user +
    "<|eot_id|><|start_header_id|>assistant<|end_header_id|>\n\n"
  );
}

export default function QloraRagPromptAnalysis() {
  const [medium, setMedium] = useCanvasState<Medium>("medium", "blog");
  const [topicId, setTopicId] = useCanvasState("topicId", "gold_001");
  const [pane, setPane] = useCanvasState<Pane>("pane", "generate");
  const [exact, setExact] = useCanvasState("exactRendered", false);

  const topics = DRAFTS.filter((draft) => draft.medium === "blog");
  const topicIndex = Math.max(0, topics.findIndex((draft) => draft.id === topicId));
  const activeId = topics[topicIndex]?.id ?? topics[0].id;
  const draft = DRAFTS.find((item) => item.id === activeId && item.medium === medium) ?? DRAFTS[0];

  const userMessage = pane === "extract" ? draft.extractionUser : draft.generatorUser;
  const shown = exact && pane !== "output" ? chatWrapped(userMessage) : userMessage;
  const header =
    pane === "output"
      ? "Model continuation"
      : exact
        ? "Exact rendered string"
        : pane === "extract"
          ? "Extraction user message"
          : "Generator user message";

  return (
    <Stack gap={20}>
      <Stack gap={6}>
        <H1>Prompt the model received</H1>
        <Text tone="secondary">
          Each draft in `experiments/EXP-20261005-003-relabel-rag-final/raw/relabel.jsonl`
          stores two model calls. Extraction runs with the Relabel adapter off.
          Generation runs with the adapter on. The generator user message is the prompt
          to compare with deployment.
        </Text>
      </Stack>

      <H2>Same path for all 120 drafts</H2>
      <Table
        headers={["Step", "Adapter", "What is sent"]}
        rows={[
          ["1. Embed", "No LLM. nomic-embed-text", "Topic text only. No medium, no passages."],
          ["2. Extract", "Off. Same 4-bit base", "Extraction user message, including the four raw passages."],
          ["3. Generate", "On. lemkin_lora_relabel", "Generator user message. Evidence lines only. Raw passages removed."],
        ]}
        rowTone={[undefined, "warning", "info"]}
        striped
      />
      <Text size="small" tone="tertiary">
        Both model calls use one system header: Cutting Knowledge Date: December 2023, Today Date: 26 Jul 2024.
        Turn on Exact rendered string to see that header and the Llama chat markers around the user message.
      </Text>

      <Row gap={8} wrap>
        {MEDIUMS.map((item) => (
          <Pill key={item.id} active={medium === item.id} onClick={() => setMedium(item.id)}>
            {item.label}
          </Pill>
        ))}
      </Row>
      <Row gap={8} align="center">
        <Pill
          disabled={topicIndex === 0}
          onClick={() => setTopicId(topics[topicIndex - 1].id)}
        >
          Previous topic
        </Pill>
        <Pill
          disabled={topicIndex >= topics.length - 1}
          onClick={() => setTopicId(topics[topicIndex + 1].id)}
        >
          Next topic
        </Pill>
        <Text size="small" tone="secondary">
          {draft.id} · {topicIndex + 1} of {topics.length} · {draft.topic}
        </Text>
      </Row>

      <Row gap={16} align="end">
        <Stat value={draft.retrievalQuery === draft.topic ? "Topic only" : "Differs"} label="Text that was embedded" />
        <Stat value={String(draft.promptTokens)} label="Generator prompt tokens" />
        <Stat value={String(draft.maxNewTokens)} label="Generator max new tokens" />
        <Stat value={String(draft.seed)} label="Generation seed" />
      </Row>

      <Table
        headers={["Check on this draft", "Result"]}
        rows={[
          ["Embedded string", draft.retrievalQuery],
          ["Raw passage text inside generator prompt", draft.rawInGenerator ? "Yes" : "No"],
          ["Evidence block inside generator prompt", draft.evidenceInGenerator ? "Yes" : "No"],
          ["Adapter disabled for extraction", draft.adapterOff ? "Yes" : "No"],
          ["Extraction max new tokens", String(draft.extractionMaxTokens)],
        ]}
        rowTone={[
          undefined,
          draft.rawInGenerator ? "danger" : "success",
          draft.evidenceInGenerator ? "success" : "danger",
          draft.adapterOff ? "success" : "danger",
          undefined,
        ]}
      />

      <Stack gap={8}>
        <Row gap={8} wrap align="center">
          {PANES.map((item) => (
            <Pill key={item.id} active={pane === item.id} onClick={() => setPane(item.id)}>
              {item.label}
            </Pill>
          ))}
          {pane !== "output" ? (
            <Row gap={8} align="center">
              <Text size="small">Exact rendered string</Text>
              <Toggle checked={exact} onChange={setExact} />
            </Row>
          ) : null}
        </Row>
        {pane === "generate" ? (
          <Callout tone="info" title="This is the generation prompt">
            Relabel adapter enabled. The model continued after this user message. Raw retrieved passages are not in this prompt.
          </Callout>
        ) : null}
        {pane === "extract" ? (
          <Callout tone="warning" title="This prompt is not the generation prompt">
            Adapter disabled. The four source passages are in this message. Their claims are distilled, then this text is discarded before Relabel writes the draft.
          </Callout>
        ) : null}
        {pane === "output" ? (
          <Callout tone="neutral" title="Continuation after the generator prompt">
            Stored as answer. Stop reason {draft.stop}.
            {draft.unsupported ? " An unsupported number was flagged." : ""}
            {draft.copied ? " A source-copy flag fired." : ""}
          </Callout>
        ) : null}
      </Stack>

      <Card>
        <CardHeader trailing={draft.id}>{header}</CardHeader>
        <CardBody>
          <Text style={{ whiteSpace: "pre-wrap" }}>{shown}</Text>
        </CardBody>
      </Card>

      {pane === "extract" ? (
        <Stack gap={8}>
          <H2>Passages placed in the extraction prompt</H2>
          <Text size="small" tone="tertiary">
            Cosine distance from the topic embedding. These rows are the source passages, not the evidence lines the generator saw.
          </Text>
          <Table
            headers={["Source", "Medium", "Distance", "Passage"]}
            columnAlign={["left", "left", "right", "left"]}
            rows={draft.hits.map((hit) => [hit.id, hit.medium, hit.distance, hit.text])}
            striped
          />
        </Stack>
      ) : null}
    </Stack>
  );
}
